def sphere(x: np.ndarray) -> np.ndarray:
  return -np.sum(np.square(x), axis=-1)


def rastrigin_d10(x: np.ndarray) -> np.ndarray:
  return 10 * np.sum(
      np.cos(2 * np.pi * x), axis=-1) - np.sum(
          np.square(x), axis=-1)


