def __init__(self, time_: _TimeObjectType, expire: _TimeType):
    self.__time = time_
    self.__time_proxy = TimeProxy(self.__time, frozen=False)
    self.__init_time = self.__time_proxy.time()
    self.__expire = expire

    self.__methods = {}
